export const telecomLessons=definitions.map(([id,title,section,explain,labels,question,choices,answer,source])=>({id,title,section,explain,question,choices,answer,source,track:'network',conceptLab:true,visual:'network',scene:'network',tag:'NETWORK / PROVIDER LAB',time:25,subtitle:'เทียบสถานการณ์ แล้วอธิบายการตัดสินใจและผลต่อบริการ',scenario:labels[0],states:labels.map(label=>({label,headline:label,rows:[['Scope','เครือข่ายสมมติ; ไม่ใช่ระบบ NT']],detail:'กดเล่นขั้นตอนด้านบน เปรียบเทียบข้อมูลและจุดตัดสินใจ',ok:true})),steps:['อ่าน topology และสมมติฐาน','เล่นอย่างน้อยสองสถานการณ์จนจบ','ตอบภารกิจจากหลักฐาน'],work:'เล่นสองสถานการณ์จนจบ แล้วบอกว่าจุดใดเปลี่ยนและมีผลต่อบริการอย่างไร',hint:explain,reason:explain}));
